CREATE TABLE mq_outbox (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, event_id VARCHAR(64) NOT NULL, aggregate_type VARCHAR(64) NOT NULL, aggregate_id VARCHAR(64) NOT NULL, aggregate_version BIGINT NOT NULL, event_type VARCHAR(128) NOT NULL, event_version VARCHAR(16) NOT NULL, payload JSON NOT NULL, status VARCHAR(16) NOT NULL, retry_count INT NOT NULL DEFAULT 0, next_retry_at DATETIME(3) NULL, claim_token VARCHAR(128) NULL, created_at DATETIME(3) NOT NULL, published_at DATETIME(3) NULL, UNIQUE KEY uk_outbox_event(event_id), KEY idx_outbox_poll(status,next_retry_at,id));
CREATE TABLE mq_inbox (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, consumer_group VARCHAR(128) NOT NULL, event_id VARCHAR(64) NOT NULL, aggregate_version BIGINT NULL, status VARCHAR(16) NOT NULL, processed_at DATETIME(3) NULL, error_message VARCHAR(1024) NULL, UNIQUE KEY uk_inbox(tenant_id,consumer_group,event_id));
CREATE TABLE integration_task (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, task_type VARCHAR(64) NOT NULL, business_type VARCHAR(32) NULL, business_id BIGINT NULL, event_id VARCHAR(64) NULL, trace_id VARCHAR(128) NULL, status VARCHAR(32) NOT NULL, retry_count INT NOT NULL DEFAULT 0, next_retry_at DATETIME(3) NULL, last_error_code VARCHAR(128) NULL, last_error_message TEXT NULL, owner_user_id BIGINT NULL, manual_required TINYINT NOT NULL DEFAULT 0, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, KEY idx_int_task(tenant_id,status,next_retry_at));
CREATE TABLE idempotency_record (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, user_id BIGINT NULL, api_code VARCHAR(128) NOT NULL, idempotency_key VARCHAR(128) NOT NULL, request_hash VARCHAR(128) NOT NULL, response_code VARCHAR(128) NULL, response_body JSON NULL, status VARCHAR(16) NOT NULL, expire_at DATETIME(3) NOT NULL, created_at DATETIME(3) NOT NULL, UNIQUE KEY uk_idem(tenant_id,user_id,api_code,idempotency_key));
CREATE TABLE audit_log (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, operator_id BIGINT NULL, support_session_id BIGINT NULL, business_type VARCHAR(32) NOT NULL, business_id BIGINT NOT NULL, action VARCHAR(128) NOT NULL, before_snapshot JSON NULL, after_snapshot JSON NULL, reason VARCHAR(1024) NULL, ip VARCHAR(64) NULL, device VARCHAR(256) NULL, trace_id VARCHAR(128) NULL, created_at DATETIME(3) NOT NULL, KEY idx_audit_biz(tenant_id,business_type,business_id,created_at));
CREATE TABLE export_task (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, task_no VARCHAR(64) NOT NULL, export_type VARCHAR(64) NOT NULL, request_json JSON NOT NULL, status VARCHAR(32) NOT NULL, file_id BIGINT NULL, created_by BIGINT NOT NULL, created_at DATETIME(3) NOT NULL, completed_at DATETIME(3) NULL, UNIQUE KEY uk_export_task(tenant_id,task_no));
CREATE TABLE import_task (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, task_no VARCHAR(64) NOT NULL, import_type VARCHAR(64) NOT NULL, source_file_id BIGINT NOT NULL, status VARCHAR(32) NOT NULL, total_rows BIGINT NOT NULL DEFAULT 0, success_rows BIGINT NOT NULL DEFAULT 0, failed_rows BIGINT NOT NULL DEFAULT 0, created_by BIGINT NOT NULL, created_at DATETIME(3) NOT NULL, UNIQUE KEY uk_import_task(tenant_id,task_no));
